  let s = seed * 9301 + 49297;
  for (let i = 0; i < p.length; i++) {
    s = (s * 9301 + 49297) % 233280;
    p[i] = s / 233280;
  }
  const at = (x, y) => p[(x & 63) + (y & 63) * 64 & 4095];
  return (x, y) => {
    const xi = Math.floor(x),
      yi = Math.floor(y),
      xf = x - xi,
      yf = y - yi;
    const u = xf * xf * (3 - 2 * xf),
      v = yf * yf * (3 - 2 * yf);
    const a = at(xi, yi),
      b = at(xi + 1, yi),
      c = at(xi, yi + 1),
      d = at(xi + 1, yi + 1);
    return a * (1 - u) * (1 - v) + b * u * (1 - v) + c * (1 - u) * v + d * u * v;
  };
